insert into coding_tests (domain_slug,topic,title,problem,input_desc,output_desc,example_input,example_output,hints,difficulty) values
('fullstack','JavaScript Basics','Reverse a String','Write a function that reverses a string without using the built-in reverse method','A string s','The reversed string','hello','olleh',ARRAY['Use a for loop','Split the string into characters','Build the result from end to start'],'beginner'),
('fullstack','DOM Manipulation','Build a Todo List','Create a function that adds an item to a todo array and returns the updated array','An array of strings and a new item string','Updated array with new item appended','array and new item','updated array with new item',ARRAY['Use the push method','Return the modified array','Handle empty array case'],'beginner'),
('fullstack','Async JavaScript','Fetch User Data','Write an async function that fetches user data from an API and returns the user name','A user ID number','The user name as a string','1','Leanne Graham',ARRAY['Use fetch with async await','Access the json method on response','Handle errors with try catch'],'intermediate'),
('dsa','Arrays','Two Sum Problem','Find two numbers in an array that add up to target and return their indices','An array of integers and a target number','Array of two indices that sum to target','[2,7,11,15] target=9','[0,1]',ARRAY['Use a hash map for O(n) solution','For each number check if target minus number exists','Store number and index in the map'],'beginner'),
('dsa','Binary Search','Search in Sorted Array','Implement binary search to find a target in a sorted array','A sorted array and a target value','Index of target or -1 if not found','[1,3,5,7,9] target=5','2',ARRAY['Use left and right pointers','Calculate mid as left plus right divided by 2','Move left or right based on comparison'],'beginner'),
('dsa','Dynamic Programming','Fibonacci Sequence','Calculate the nth Fibonacci number using dynamic programming','A number n','The nth Fibonacci number','10','55',ARRAY['Use memoization or bottom-up tabulation','Base cases are fib(0)=0 and fib(1)=1','Build solution from smaller subproblems'],'intermediate'),
('ml','Python','Normalize Array','Write a function to normalize an array to values between 0 and 1','An array of numbers','Normalized array where min=0 and max=1','[1,2,3,4,5]','[0.0, 0.25, 0.5, 0.75, 1.0]',ARRAY['Find min and max of array','Subtract min from each element','Divide by the range max minus min'],'beginner'),
('ml','Statistics','Calculate Mean and Std','Write a function that returns mean and standard deviation of a dataset','An array of numbers','Object with mean and std properties','[2,4,4,4,5,5,7,9]','mean 5.0 std 2.0',ARRAY['Calculate mean as sum divided by length','Variance is average of squared differences from mean','Standard deviation is square root of variance'],'beginner'),
('ml','Linear Regression','Gradient Descent Step','Implement one step of gradient descent for linear regression','Arrays x y and learning rate alpha','Updated weights w and b','x=[1,2,3] y=[2,4,6] w=0 b=0 alpha=0.1','w=0.28 b=0.12',ARRAY['Calculate predictions as w*x + b','Compute gradients using chain rule','Update w and b using learning rate'],'intermediate'),
('ai','Search','Implement BFS','Implement breadth first search on a graph represented as adjacency list','Graph as dict and start node','List of nodes visited in BFS order','A connects to B and C, B connects to D, start=A','[A,B,C,D,E]',ARRAY['Use a queue data structure','Mark nodes as visited when enqueued','Process each node and add its neighbors'],'beginner'),
('ai','Logic','Evaluate Expression','Evaluate a boolean logic expression with AND OR NOT operators','A string expression with AND OR NOT and variables','Boolean result true or false','A AND NOT B where A=true B=false','true',ARRAY['Parse the expression into tokens','Handle operator precedence NOT AND OR','Use recursive descent or a stack'],'intermediate'),
